window.v37CommitPremiumMock=function(m){
  if(!m||m.v37Committed)return m;
  const st=qstats(),log=answerLog(),answers=[];let correct=0;
  m.v25Times=m.v25Times||{};
  Object.entries(m.selections||{}).forEach(([id,index])=>{
    const q=QUESTIONS.find(x=>String(x.id)===String(id));if(!q)return;
    const ok=Number(index)===q.answer,seconds=Math.max(1,Math.round((m.v37Times?.[id]||1)));
    st[id]??={attempts:0,correct:0,wrong:0,last:null};st[id].attempts++;st[id].last=todayISO();if(ok){st[id].correct++;correct++}else st[id].wrong++;
    log.push({ts:Date.now(),date:todayISO(),id:q.id,ok,subject:q.subject,topic:q.topic,exam:q.exam,module:q.module||null,seconds,mode:'mock'});
    scheduleReview(q.id,ok,false);m.v25Times[id]=seconds;answers.push({id:q.id,ok,subject:q.subject});
  });
  if(log.length>2500)log.splice(0,log.length-2500);save(KEYS.stats,st);vsave(V25.answerLog,log);m.answers=answers;m.correct=correct;m.v37Committed=true;return m;
};
