function smartScore(q){const st=qstats()[q.id],last=lastMap()[q.id],review=jload(REVIEW_KEY,{}),rows=topicRows(),r=rows.find(x=>x.subject===q.subject&&x.topic===q.topic);let s=0;if(review[q.id]?.due&&review[q.id].due<=todayISO())s+=85;if((st?.wrong||0)>0&&last?.ok===false)s+=70;if(r)s+=(100-r.score)*.55;if(!st)s+=38;if(last&&!last.ok)s+=20;if((st?.attempts||0)>3&&last?.ok)s-=18;s+=Math.random()*12;return s}
