app.questionMode=localStorage.getItem('study_question_mode_v3')||app.settings.focusExam||'ENEM';
function questionAreasFor(exam){return [...new Set(QUESTIONS.filter(q=>q.exam===exam).map(q=>q.area).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR'))}
function syncQuestionSubjects(){const ex=document.getElementById('qExam')?.value||app.questionMode,mod=document.getElementById('qModule')?.value||'ALL',area=document.getElementById('qArea')?.value||'ALL',sel=document.getElementById('qSubject');if(!sel)return;const old=sel.value;const subs=[...new Set(QUESTIONS.filter(q=>q.exam===ex&&(mod==='ALL'||q.module===mod)&&(area==='ALL'||q.area===area)).map(q=>q.subject))].sort((a,b)=>a.localeCompare(b,'pt-BR'));sel.innerHTML='<option value="ALL">Todas as matérias</option>'+subs.map(s=>`<option>${esc(s)}</option>`).join('');if(subs.includes(old))sel.value=old}
function syncQuestionModeFilters(){const ex=app.questionMode;const exam=document.getElementById('qExam'),mod=document.getElementById('qModule'),area=document.getElementById('qArea'),banner=document.getElementById('questionModeBanner'),title=document.getElementById('questionModeTitle'),sub=document.getElementById('questionModeSub');if(exam)exam.value=ex;if(mod){mod.disabled=ex!=='PISM';if(ex!=='PISM')mod.value='ALL';else if(mod.value==='ALL')mod.value=app.settings.pismModule||'I'}if(area){const old=area.value;const areas=questionAreasFor(ex);area.innerHTML='<option value="ALL">Todas as áreas</option>'+areas.map(a=>`<option>${esc(a)}</option>`).join('');if(areas.includes(old))area.value=old;else area.value='ALL'}if(banner)banner.classList.toggle('pism',ex==='PISM');if(title)title.textContent=ex==='ENEM'?'Questões ENEM':'Questões PISM';if(sub){const records=QUESTIONS.filter(q=>q.exam===ex),families=uniqueFamilyPool(records).length;sub.textContent=ex==='ENEM'?`${families} famílias de questões (${records.length} variações editoriais) por área, matéria e assunto.`:`${families} famílias de questões (${records.length} variações editoriais) com módulo, área, matéria e assunto.`;}document.querySelectorAll('[data-qmode]').forEach(b=>b.classList.toggle('active',b.dataset.qmode===ex));syncQuestionSubjects();refreshTopicFilter();if(window.lucide)lucide.createIcons()}
