window.correctEssayWithAI=async function(){const text=document.getElementById('essayText').value.trim(),theme=document.getElementById('essayTheme').textContent.trim(),title=document.getElementById('essayTitle').value.trim(),host=document.getElementById('aiCorrectionResult'),status=document.getElementById('aiCorrectionStatus'),btn=document.getElementById('aiCorrectBtn');if(text.split(/\s+/).filter(Boolean).length<80){toast('Escreva uma redação mais completa antes da correção por IA.');return}if(btn?.disabled)return;status.textContent='Analisando C1–C5 com IA...';if(btn){btn.disabled=true;btn.textContent='Corrigindo...'}host.innerHTML='<div class="notice">Correção em andamento. O resultado é uma estimativa pedagógica e não substitui a correção oficial.</div>';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),80000);try{const r=await fetch('/api/correct-essay',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({text,theme,title})});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||`Falha na correção (${r.status})`);renderAICorrection(data);status.textContent='Correção concluída · estimativa pedagógica por IA'}catch(e){const msg=e?.name==='AbortError'?'A correção demorou além do limite. Tente novamente.':e.message;host.innerHTML=`<div class="notice"><strong>Não foi possível concluir a correção.</strong><br>${esc(msg)}<br><br>Confirme se a V3 está aberta pelo servidor e se OPENAI_API_KEY está configurada no arquivo .env.</div>`;status.textContent='Correção não concluída'}finally{clearTimeout(timer);if(btn){btn.disabled=false;btn.innerHTML='<i data-lucide="sparkles" class="icon"></i>Corrigir com IA';if(window.lucide)lucide.createIcons()}}}
function renderAICorrection(d){const host=document.getElementById('aiCorrectionResult');const scores=d.scores||{};const comps=['c1','c2','c3','c4','c5'];host.innerHTML=`<div class="ai-score-grid">${comps.map(c=>`<div class="ai-score"><span>${c.toUpperCase()}</span><b>${Number(scores[c]||0)}</b></div>`).join('')}</div><div class="ai-total"><span>Nota estimada</span><b>${Number(d.total||0)}/1000</b></div><div class="ai-feedback"><div><h4>Pontos fortes</h4><ul>${(d.strengths||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Sem dados.</li>'}</ul></div><div><h4>Prioridades de melhoria</h4><ul>${(d.priorities||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Sem dados.</li>'}</ul></div></div><div class="notice" style="margin-top:10px"><strong>Leitura geral</strong><br>${esc(d.summary||'')}</div>${d.competencies?`<div style="margin-top:10px">${comps.map(c=>`<div class="notice" style="margin-top:7px"><strong>${c.toUpperCase()} · ${Number(scores[c]||0)}</strong><br>${esc(d.competencies[c]||'')}</div>`).join('')}</div>`:''}`}
