function v35CountQuestions(blocks){return blocks.reduce((n,b)=>{const a=b.action;if(!a)return n;if(a.kind==='drill')return n+(a.payload.count||0);if(a.kind==='pismDay')return n+20;if(a.kind==='areaMock')return n+45;return n},0)}
function v35Render(minutes,data){const host=document.getElementById('v34GeneratedRoute');if(!host)return;const total=data.blocks.reduce((a,b)=>a+b.m,0),qCount=v35CountQuestions(data.blocks),review=v35ReviewCount();host.innerHTML=`<div class="v35-plan-summary"><div class="main"><b>${esc(data.identity)} · ${fmtMin(total)}</b><span>${esc(data.routeLabel)}. O plano alterna prática ativa, correção e recuperação de atenção; os botões abrem cada ferramenta do app.</span></div><div class="v35-plan-kpi"><strong>${qCount||'—'}</strong><span>questões planejadas</span></div><div class="v35-plan-kpi"><strong>${review}</strong><span>revisões pendentes</span></div><div class="v35-plan-kpi"><strong>${data.weak?esc(data.weak.subject):'—'}</strong><span>prioridade atual</span></div></div>`+data.blocks.map((b,i)=>`<div class="v27-block v35-block ${b.type||''}"><div class="v27-block-time">${b.m}m</div><div><div class="v35-block-index">Etapa ${i+1}</div><b>${esc(b.title)}</b><span>${esc(b.desc)}</span><div class="v35-purpose">Objetivo: ${esc(b.purpose)}</div></div>${b.action?`<button class="btn btn-sm ${b.type==='exam'?'btn-pism':'btn-primary'}" onclick='runQuickAction(${JSON.stringify(b.action).replace(/'/g,"&#39;")})'>${esc(b.action.label)}</button>`:''}</div>`).join('')+`<div class="v35-plan-footer"><b>Regra do plano:</b> se um bloco gerar muitos erros, não compense aumentando volume. Use a correção e a revisão antes de avançar; isso é o que transforma prática em acerto futuro.</div>`;localStorage.setItem(V35.lastMinutes,String(minutes));if(window.lucide)lucide.createIcons()}
function openPismDiscursivesForPlan(module,day){const subjects=module==='III'?(PISM_III_DISC[app.settings.pismCourseArea]?.[day]||[]).map(x=>x[0]):v35PismSubjects(module,day);go('mocks');const sel=document.getElementById('discModule');if(sel)sel.value=module;const arr=PISM_DISCURSIVE.filter(x=>x.module===module&&subjects.includes(x.subject));const host=document.getElementById('discursiveList');if(host){host.innerHTML=arr.length?arr.map(x=>`<div class="card discursive"><div class="q-meta"><span class="tag pism">PISM</span><span class="tag">Módulo ${esc(x.module)}</span><span class="tag">${esc(x.subject)}</span><span class="tag">${esc(x.topic)}</span></div><h4>${esc(x.prompt)}</h4><textarea class="field" style="min-height:110px;resize:vertical" placeholder="Escreva sua resposta para treinar..."></textarea><button class="btn btn-sm btn-secondary" style="margin-top:9px" onclick="this.nextElementSibling.classList.toggle('show')">Ver critérios de autocorreção</button><div class="rubric">${x.rubric.map(r=>`<div>• ${esc(r)}</div>`).join('')}</div></div>`).join(''):`<div class="empty">Ainda não há proposta discursiva autoral cadastrada para este recorte. Use o painel editorial para ampliar o banco.</div>`}setTimeout(()=>host?.scrollIntoView({behavior:'smooth',block:'start'}),80);if(window.lucide)lucide.createIcons()}
window.runQuickAction=function(action){if(!action)return;const p=action.payload||{};if(action.kind==='review'){if(window.startDueReview)window.startDueReview();return}if(action.kind==='essay'){go('essay');return}if(action.kind==='discursive'){if((p.module||app.settings.pismModule)==='III'&&!app.settings.pismCourseArea){toast('Selecione a área do curso do PISM III antes do treino discursivo.');go('settings');setTimeout(()=>document.getElementById('setPismCourseArea')?.focus(),80);return}openPismDiscursivesForPlan(p.module||app.settings.pismModule,p.day||1);return}if(action.kind==='areaMock'){if(window.startEnemAreaMock)window.startEnemAreaMock(p.area);return}if(action.kind==='pismDay'){if(p.module){app.settings.focusExam='PISM';app.settings.pismModule=p.module;save(KEYS.settings,app.settings)}if(window.startPismDayMock)window.startPismDayMock(p.day,p.minutes||70);return}if(action.kind==='drill'){startQuickTargetDrill(p);return}}
window.startQuickTargetDrill=function(p){let pool=QUESTIONS.filter(q=>q.exam===p.exam&&(p.exam!=='PISM'||!p.module||q.module===p.module)&&(!p.areas||p.areas.includes(q.area))&&(!p.subjects||p.subjects.includes(q.subject))&&(!p.subject||q.subject===p.subject)&&(!p.topic||q.topic===p.topic));if(pool.length<(p.count||5)&&p.topic)pool=QUESTIONS.filter(q=>q.exam===p.exam&&(p.exam!=='PISM'||!p.module||q.module===p.module)&&(!p.areas||p.areas.includes(q.area))&&(!p.subjects||p.subjects.includes(q.subject))&&(!p.subject||q.subject===p.subject));pool=v35FamilyPool(pool);const st=qstats();pool=[...pool].sort((a,b)=>{const sa=familyStats(a,st),sb=familyStats(b,st),ra=sa.attempts?sa.correct/sa.attempts:.45,rb=sb.attempts?sb.correct/sb.attempts:.45;const wa=(sa.wrong||0)*3+(sa.answered?0:8)+(1-ra)*10,wb=(sb.wrong||0)*3+(sb.answered?0:8)+(1-rb)*10;return wb-wa||Math.random()-.5});const picked=pool.slice(0,Math.min(p.count||10,pool.length));if(!picked.length)return toast('Não há questões suficientes nesse recorte.');app.mock=null;app.v25Review=null;app.v27Drill={ids:picked.map(q=>q.id),index:0,minutes:p.minutes||30,mode:'approval35',started:Date.now(),correct:0,label:p.label||'Rota de aprovação'};app.currentQuestion=picked[0];go('questions');if(window.renderQuestion)window.renderQuestion();toast(`${p.label||'Treino'} · ${picked.length} questões`)}
window.setQuickTrack=function(track){localStorage.setItem(V35.track,track);const oldRoute=localStorage.getItem(V35.route);const map=v34RouteMap(track);if(!oldRoute||!map[oldRoute])localStorage.setItem(V35.route,v34DefaultRoute(track));if(track==='ENEM'){app.settings.focusExam='ENEM'}else{app.settings.focusExam='PISM';app.settings.pismModule=v34Module(track)}save(KEYS.settings,app.settings);syncExamUI();syncQuickPlannerUI();renderDashboard();generatePlan();const last=+(localStorage.getItem(V35.lastMinutes)||0);if(last)buildQuickPlan(last)}
window.setQuickRoute=function(route){localStorage.setItem(V35.route,route);syncQuickPlannerUI();const last=+(localStorage.getItem(V35.lastMinutes)||0);if(last)buildQuickPlan(last)}
