function saveQuestionTime(){const m=app.mock;if(!m?.premium)return;const id=m.ids[m.index],now=Date.now(),sec=Math.max(0,(now-(m.v37QuestionStarted||now))/1000);m.v37Times[id]=(m.v37Times[id]||0)+sec;m.v37QuestionStarted=now}
function premiumClockText(){const m=app.mock;if(!m?.premium)return'--:--';if(m.deadline){const left=Math.max(0,Math.ceil((m.deadline-Date.now())/1000));return`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`}const elapsed=Math.max(0,Math.floor((Date.now()-m.started)/1000));return`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`}
function updatePremiumClock(){const m=app.mock;if(!m?.premium)return;const el=document.getElementById('v37ExamTime');if(el){el.textContent=premiumClockText();if(m.deadline){const left=Math.max(0,Math.ceil((m.deadline-Date.now())/1000));el.classList.toggle('urgent',left<=120);if(left<=0)return window.finishMock(true)}}}
function paletteHtml(m){return m.ids.map((id,i)=>{const answered=Object.prototype.hasOwnProperty.call(m.selections,id),marked=(m.marked||[]).includes(id);return`<button class="${answered?'answered ':''}${marked?'marked ':''}${i===m.index?'current':''}" onclick="premiumJump(${i})">${i+1}</button>`}).join('')}
function renderPremiumMockQuestion(){const m=app.mock;if(!m?.premium)return;clearInterval(app.v37MockTicker);const q=QUESTIONS.find(x=>x.id===m.ids[m.index]);if(!q)return;app.currentQuestion=q;m.v37QuestionStarted=Date.now();const selected=m.selections[q.id],marked=(m.marked||[]).includes(q.id),answered=Object.keys(m.selections).length;const card=document.getElementById('questionCard');card.innerHTML=`<div class="v37-exam-dock"><div class="left"><strong>Modo Prova Premium</strong><span class="tag ${q.exam.toLowerCase()}">${q.exam}</span><span class="small muted">${m.index+1}/${m.ids.length} · ${answered} respondida(s)</span></div><div class="right"><span class="small muted">${m.deadline?'restante':'decorrido'}</span><b class="v37-exam-time" id="v37ExamTime">${premiumClockText()}</b></div></div><div class="v37-exam-shell"><div class="v37-exam-main"><div class="v37-premium-question"><div class="q-meta"><span class="tag ${q.exam.toLowerCase()}">${q.exam}</span>${q.module?`<span class="tag">Módulo ${q.module}</span>`:''}<span class="tag">${esc(q.subject)}</span><span class="tag">${esc(q.topic)}</span><span class="tag">${esc(q.difficulty)}</span></div><div class="q-text">${esc(q.text)}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${Number(selected)===i?'selected':''}" onclick="answerQuestion('${q.id}',${i})"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(o)}</span></button>`).join('')}</div><div class="notice" style="margin-top:14px"><strong>Feedback bloqueado até o final.</strong><br>Você pode trocar a alternativa, voltar para questões anteriores e marcar itens para revisão.</div><div class="v37-exam-controls"><div class="group"><button class="btn btn-secondary" onclick="premiumPrev()" ${m.index===0?'disabled':''}><i data-lucide="arrow-left" class="icon"></i>Anterior</button><button class="btn btn-secondary v37-mark-btn ${marked?'active':''}" onclick="togglePremiumMark()"><i data-lucide="bookmark" class="icon"></i>${marked?'Marcada':'Marcar'}</button></div><div class="group"><button class="btn btn-secondary" onclick="premiumNext()" ${m.index===m.ids.length-1?'disabled':''}>Próxima<i data-lucide="arrow-right" class="icon"></i></button><button class="btn btn-primary" onclick="finishPremiumFromUI()">Finalizar prova</button></div></div></div></div><aside class="v37-premium-nav"><h4>Cartão de navegação</h4><p>Use para voltar a qualquer questão. O ponto indica marcação para revisar.</p><div class="v37-palette">${paletteHtml(m)}</div><div class="v37-palette-legend"><span><i class="v37-dot"></i>não respondida</span><span><i class="v37-dot answered"></i>respondida</span><span><i class="v37-dot marked"></i>marcada</span></div></aside></div>`;app.v37MockTicker=setInterval(updatePremiumClock,1000);updatePremiumClock();if(window.lucide)lucide.createIcons()}
window.answerQuestion=function(id,index){if(app.mock?.premium){app.mock.selections[id]=Number(index);document.querySelectorAll('.v37-premium-question .option').forEach((b,i)=>b.classList.toggle('selected',i===Number(index)));const nav=document.querySelector('.v37-palette');if(nav)nav.innerHTML=paletteHtml(app.mock);return}return baseAnswer37(id,index)};
window.renderMockQuestion=function(){if(app.mock?.premium)return renderPremiumMockQuestion();return baseMockRender37()};
window.premiumJump=function(i){if(!app.mock?.premium)return;saveQuestionTime();app.mock.index=Math.max(0,Math.min(app.mock.ids.length-1,i));renderPremiumMockQuestion()};
