function addPremiumAutopsy(snapshot,timeout){const result=document.getElementById('mockResult');if(!result)return;const wrong=snapshot.answers.filter(x=>!x.ok),unanswered=snapshot.ids.length-snapshot.answers.length,times=Object.values(snapshot.v25Times||{}),avg=times.length?times.reduce((a,b)=>a+b,0)/times.length:0;const quickWrong=wrong.filter(x=>(snapshot.v25Times?.[x.id]||0)<Math.max(18,avg*.55)).length,slowWrong=wrong.filter(x=>(snapshot.v25Times?.[x.id]||0)>Math.max(45,avg*1.5)).length,by={};wrong.forEach(x=>by[x.subject]=(by[x.subject]||0)+1);const weak=Object.entries(by).sort((a,b)=>b[1]-a[1])[0],marked=(snapshot.marked||[]).length,wrongIds=wrong.map(x=>x.id);localStorage.setItem(LAST_ERRORS,JSON.stringify(wrongIds));let diagnosis='Seu próximo treino deve partir dos erros, não do percentual bruto.';if(quickWrong>=2)diagnosis='Há sinais de respostas erradas muito rápidas. Revise leitura de comando e eliminação de distratores antes de aumentar velocidade.';else if(slowWrong>=2)diagnosis='Alguns erros consumiram muito tempo. Treine reconhecimento de rota de solução e critérios para abandonar uma questão temporariamente.';else if(unanswered)diagnosis='Questões em branco indicam que gestão de tempo e navegação ainda precisam entrar no treino.';result.insertAdjacentHTML('beforeend',`<div class="v37-autopsy"><h3>Autópsia do simulado</h3><div class="v37-autopsy-grid"><div class="v37-autopsy-box"><span>Não respondidas</span><b>${unanswered}</b></div><div class="v37-autopsy-box"><span>Marcadas</span><b>${marked}</b></div><div class="v37-autopsy-box"><span>Erros muito rápidos</span><b>${quickWrong}</b></div><div class="v37-autopsy-box"><span>Erros demorados</span><b>${slowWrong}</b></div></div><div class="notice"><strong>${weak?`Maior concentração de erros: ${esc(weak[0])}`:'Execução equilibrada entre matérias'}</strong><br>${esc(diagnosis)}<br><span class="tiny muted">Classificações por tempo são sinais de execução, não diagnósticos definitivos da causa do erro.</span></div>${wrongIds.length?`<button class="btn btn-primary" style="margin-top:12px" onclick="startLastMockErrors()"><i data-lucide="rotate-ccw" class="icon"></i>Treinar erros deste simulado</button>`:''}</div>`);if(window.lucide)lucide.createIcons()}
window.finishMock=function(timeout=false){if(!app.mock?.premium)return baseFinish37(timeout);saveQuestionTime();const m=app.mock,unanswered=m.ids.length-Object.keys(m.selections||{}).length;if(unanswered&&!timeout&&!confirm(`Ainda há ${unanswered} questão(ões) sem resposta. Finalizar mesmo assim?`))return;clearInterval(app.v37MockTicker);app.v37MockTicker=null;window.v37CommitPremiumMock?.(m);const snapshot={ids:[...m.ids],answers:(m.answers||[]).map(x=>({...x})),v25Times:{...(m.v25Times||{})},marked:[...(m.marked||[])],cfg:{...m.cfg}};document.body.classList.remove('v37-premium-running');baseFinish37(timeout);setTimeout(()=>addPremiumAutopsy(snapshot,timeout),0)};
window.startLastMockErrors=function(){let ids=[];try{ids=JSON.parse(localStorage.getItem(LAST_ERRORS)||'[]')}catch{}ids=ids.filter(id=>QUESTIONS.some(q=>String(q.id)===String(id)));if(!ids.length)return toast('Nenhum erro do último simulado disponível.');app.mock=null;app.v25Review=null;app.v27Drill={ids,index:0,minutes:0,mode:'v37-last-mock-errors',started:Date.now(),correct:0,label:'Erros do último simulado'};app.currentQuestion=QUESTIONS.find(q=>String(q.id)===String(ids[0]));go('questions');renderQuestion();toast(`Revisão pós-simulado · ${ids.length} questão(ões)`)};
