/* ===== V3.8 Clean ===== */

(function(){
  const baseDash38 = window.renderDashboard;
  const baseGo38 = window.go;
  window.v38OpenRoute = function(route){
    if(route === 'ENEM'){
      app.settings.focusExam='ENEM';
      save(KEYS.settings, app.settings);
      syncExamUI();
      openQuestionMode('ENEM');
      return;
    }
    const mod = (route.split('-')[1]||'I');
    app.settings.focusExam='PISM';
    app.settings.pismModule = mod;
    save(KEYS.settings, app.settings);
    syncExamUI();
    openQuestionMode('PISM');
  };
  function renderV38Home(){
    const today=todayISO();
    const st=totalQStats();
    const ss=sessions();
    const todayMin=ss.filter(x=>x.dateISO===today).reduce((a,x)=>a+(x.minutes||0),0);
    const cutoff=new Date(); cutoff.setDate(cutoff.getDate()-6);
    const cut=cutoff.toISOString().slice(0,10);
    const week=ss.filter(x=>(x.dateISO||'')>=cut).reduce((a,x)=>a+(x.minutes||0),0);
    const due=dueReviews();
    const prep=prepIndex();
    const weak=weakestRows().filter(x=>x.attempts||x.score===0)[0];
    const exam = app.settings.focusExam==='PISM' ? `PISM ${app.settings.pismModule}` : 'ENEM';
    const badge=document.getElementById('v38ExamBadge'); if(badge) badge.textContent=exam;
    const statToday=document.getElementById('v38StatToday'); if(statToday) statToday.textContent=fmtMin(todayMin);
    const statQuestions=document.getElementById('v38StatQuestions'); if(statQuestions) statQuestions.textContent=String(st.answered);
    const statStreak=document.getElementById('v38StatStreak'); if(statStreak) statStreak.textContent=`${updateStreak()} dia(s)`;
    const statPrep=document.getElementById('v38StatPrep'); if(statPrep) statPrep.textContent=`${prep.score}/100`;
    const reviewCount=document.getElementById('v38ReviewCount'); if(reviewCount) reviewCount.textContent=String(due.length);
    const weakPoint=document.getElementById('v38WeakPoint'); if(weakPoint) weakPoint.textContent=weak?`${weak.subject}${weak.topic?` · ${weak.topic}`:''}`:'Gerar diagnóstico';
    const weekStudy=document.getElementById('v38WeekStudy'); if(weekStudy) weekStudy.textContent=fmtMin(week);
    const title=document.getElementById('v38MainTitle');
    const text=document.getElementById('v38MainText');
    const btn=document.getElementById('v38PrimaryBtn');
    if(due.length){
      if(title) title.textContent='Sua melhor ação agora é revisar.';
      if(text) text.textContent=`Você tem ${due.length} revisão(ões) pendente(s). Limpar essa fila melhora retenção e evita repetir erros.`;
      if(btn){btn.innerHTML='<i data-lucide="brain" class="icon"></i>Abrir revisões'; btn.onclick=()=>go('reviews');}
    }else if(weak){
      if(title) title.textContent=`Ganhe pontos em ${weak.subject}.`;
      if(text) text.textContent=weak.topic?`Comece por ${weak.topic}. O app identificou esse ponto como a melhor oportunidade de avanço.`:`Esse é o assunto com maior espaço para crescimento agora.`;
      if(btn){btn.innerHTML='<i data-lucide="play" class="icon"></i>Treinar agora'; btn.onclick=()=>startSmartDrill(20,'approval');}
    }else{
      if(title) title.textContent='Comece com poucas questões e ganhe clareza.';
      if(text) text.textContent='Assim que você responder algumas questões, o app passa a priorizar matérias e conteúdos com mais precisão.';
      if(btn){btn.innerHTML='<i data-lucide="play" class="icon"></i>Começar'; btn.onclick=()=>openQuestionMode(app.settings.focusExam==='ENEM'?'ENEM':'PISM');}
    }
    if(window.lucide) lucide.createIcons();
  }
  window.renderDashboard = function(){ baseDash38(); renderV38Home(); };
  window.go = function(page){ baseGo38(page); if(page==='home') renderV38Home(); };
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(renderV38Home,100)); else setTimeout(renderV38Home,100);
})();


