(function(){
  const NOTES_KEY='study_question_notes_v42';
  let eliminateMode=false;
  const getNotes=()=>load(NOTES_KEY,{});
  const saveNotes=o=>save(NOTES_KEY,o);
  window.toggleMoreNav=function(force){
    const nav=document.getElementById('v42MoreNav'),btn=document.getElementById('v42MoreToggle');
    if(!nav||!btn)return;
    const open=typeof force==='boolean'?force:!nav.classList.contains('open');
    nav.classList.toggle('open',open);btn.classList.toggle('open',open);
    if(window.lucide)lucide.createIcons();
  };
  window.v42OpenQuestions=function(){openQuestionMode(app.settings.focusExam==='PISM'?'PISM':'ENEM')};
  window.toggleQuestionFocus=function(){
    document.body.classList.toggle('v42-question-focus');
    if(document.body.classList.contains('v42-question-focus'))toast('Modo foco ativado · Esc para sair');
  };
  window.toggleEliminateMode=function(){
    eliminateMode=!eliminateMode;
    const card=document.getElementById('questionCard');
    card?.classList.toggle('v42-eliminate-on',eliminateMode);
    const b=document.getElementById('v42EliminateBtn');if(b)b.classList.toggle('active',eliminateMode);
    toast(eliminateMode?'Eliminação ativa: clique em alternativas para riscar.':'Eliminação desativada.');
  };
  window.toggleQuestionNote=function(){
    document.getElementById('v42NoteWrap')?.classList.toggle('open');
    setTimeout(()=>document.getElementById('v42QuestionNote')?.focus(),20);
  };
  window.saveQuestionNote=function(){
    const q=app.currentQuestion,ta=document.getElementById('v42QuestionNote');if(!q||!ta)return;
    const notes=getNotes(),val=ta.value.trim();if(val)notes[q.id]=val;else delete notes[q.id];saveNotes(notes);
    const st=document.getElementById('v42NoteStatus');if(st)st.textContent=val?'Anotação salva':'Anotação removida';
  };
  function decorateQuestion42(){
    if(app.mock?.premium)return;
    const q=app.currentQuestion,card=document.getElementById('questionCard');if(!q||!card||card.querySelector('.v42-question-tools'))return;
    const notes=getNotes(),note=notes[q.id]||'';
    const toolbar=card.querySelector('.q-toolbar')||card;
    const box=document.createElement('div');box.className='v42-question-tools';
    box.innerHTML=`<details class="v42-tools-menu"><summary class="btn btn-sm btn-secondary"><i data-lucide="sliders-horizontal" class="icon"></i>Ferramentas</summary><div class="v42-tools-pop"><button class="btn btn-sm btn-secondary" id="v42EliminateBtn" onclick="toggleEliminateMode()"><i data-lucide="list-x" class="icon"></i>Eliminar alternativas</button><button class="btn btn-sm btn-secondary" onclick="toggleQuestionNote()"><i data-lucide="notebook-pen" class="icon"></i>Anotação pessoal</button><button class="btn btn-sm btn-secondary" onclick="toggleQuestionFocus()"><i data-lucide="maximize-2" class="icon"></i>Modo foco</button></div></details><div class="v42-note-wrap ${note?'open':''}" id="v42NoteWrap" style="flex-basis:100%"><textarea class="textarea" id="v42QuestionNote" placeholder="Escreva uma observação curta sobre esta questão..." oninput="saveQuestionNote()">${esc(note)}</textarea><div class="v42-note-status" id="v42NoteStatus">${note?'Anotação salva':'Salva automaticamente'}</div></div>`;
    toolbar.insertAdjacentElement('afterend',box);
    eliminateMode=false;card.classList.remove('v42-eliminate-on');
    if(window.lucide)lucide.createIcons();
  }
  const baseRender42=window.renderQuestion;
  window.renderQuestion=function(){baseRender42();decorateQuestion42();};
  const baseAnswer42=window.answerQuestion;
  window.answerQuestion=function(id,index){
    if(eliminateMode&&!app.mock){const buttons=[...document.querySelectorAll('#questionCard .option')],btn=buttons[index];btn?.classList.toggle('v42-eliminated');return;}
    return baseAnswer42(id,index);
  };
  const baseOpenMode42=window.openQuestionMode;
  window.openQuestionMode=function(exam){baseOpenMode42(exam);const s=document.getElementById('v42QuestionScope');if(s)s.textContent=exam;};
  const baseGo42=window.go;
  window.go=function(page){
    document.body.classList.remove('v42-question-focus');
    baseGo42(page);
    if(['mastery','strategy','calendar','settings'].includes(page))toggleMoreNav(true);
  };
  document.addEventListener('keydown',e=>{
    const tag=(e.target?.tagName||'').toLowerCase();if(['input','textarea','select'].includes(tag))return;
    if(e.key==='Escape'&&document.body.classList.contains('v42-question-focus')){document.body.classList.remove('v42-question-focus');toast('Modo foco encerrado');return;}
    if(!document.getElementById('page-questions')?.classList.contains('active')||app.mock)return;
    if(e.key.toLowerCase()==='n'){e.preventDefault();pickQuestion(false)}
    if(e.key.toLowerCase()==='f'&&app.currentQuestion){e.preventDefault();toggleFavorite(app.currentQuestion.id)}
  });
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{const p=localStorage.getItem(KEYS.active);if(['mastery','strategy','calendar','settings'].includes(p))toggleMoreNav(true)});else{const p=localStorage.getItem(KEYS.active);if(['mastery','strategy','calendar','settings'].includes(p))toggleMoreNav(true)}
})();


